// plugins/stickeraudio-v3.js — ستيكر صوتي (.stickeraudio) — نسخة Silana v3 (اختيار ستيكر + حدّ مدة الصوت)
// ─────────────────────────────────────────────────────────────────────────────
// مقتبس ومكيّف من كود أجنبي (©iEnz — Pastebin «Baileys Sticker Audio»)
// صيفطو المستخدم بتاريخ 2026-11-24، مع:
//  • صيغة Silana handler (export default) بدل مقتطف { m, conn } ديال الأصل
//  • صورة سيلانا الحقيقية (الماسكوت، حجاب أحمر) مضمّنة Base64 داخل الملف
//    بدل ./media/menu.jpg ديال الأصل — قاعدة الملف الواحد: حتى ملف مرافق
//  • ES2020 فقط (بلا رموز ES2021 الجديدة) حيت محلّل البانل كيرفضها
//  • الرفع: conn.waUploadToServer إلا كان متوفر، وإلا الرفع اليدوي عبر
//    media_conn (نفس طريقة sticker.js المجرّبة عندنا)
//  • ملفات مؤقتة فـ tmp/ ديال البوت (ماشي /tmp ديال النظام)
//  • واجهة بالدارجة، والتفاصيل التقنية كتبان للمالك فقط
//
// الأمر:
//   رد على فويس / أوديو واكتب: .stickeraudio
//   ← كيتصايب «ستيكر صوتي»: صورة سيلانا كستيكر، والصوت مخبّي داخل نفس
//     الرسالة عبر حقل protobuf تجريبي (134 — futureProof)، وكيتصيفط
//     بـ relayMessage مع ترقيع مؤقت لـ proto.Message.encode كيترجع
//     مباشرة بعد الإرسال (نفس حيلة الأصل بالضبط).
//
// ⚠️ ميزة تجريبية بطبيعتها: واش الصوت غادي يتسمع من الستيكر كيبقى على
//    حساب نسخة واتساب ديال المستقبِل — بعض النسخ كتبيّنو ستيكر عادي.
//    الحكم النهائي = التجربة الحية فالبانل.
// حدود: الصوت ≤ 25MB، والمدة كتقصّ عند MAX_AUDIO_SECONDS (30 ثانية — v3).
//
// ── جديد v2.1 — اختيار ستيكر لمرة واحدة (بلا حفظ دائم) ──
//   1) رد على ستيكر ولا صورة واكتب .stickeraudio ← كيتخزن «اختيار معلّق»
//      فالذاكرة (Map) مربوط بهاد الشات + هاد المستخدم، صالح 90 ثانية.
//   2) رد على الأوديو/الفويس بنفس الأمر قبل ما تسالي المدة ← الستيكر
//      الصوتي كيتصايب بالصورة المختارة بدل صورة سيلانا، والاختيار كيتمسح.
//   • سالات المدة؟ كيرجع لصورة سيلانا مع سطر كيعلن بلي الاختيار سالى.
//   • اختيار جديد كيبدّل القديم وكيعاود الـ90 ثانية من الأول.
//   • بلا اختيار معلّق: نفس سلوك v1 بالضبط (صورة سيلانا).
//
// ── جديد v3 — حدّ مدة الصوت ──
//   • الصوت أطول من MAX_AUDIO_SECONDS (30 ثانية) كيتقصّ لأول 30 ثانية
//     قبل البناء، وكيزيد سطر ✂️ فإشعار النجاح بالمدة الأصلية — حيت
//     تجربة حية (2026-11-24) بيّنات بلي ستيكر صوتي بأوديو 2:06 كيرفض
//     يتلعب فواتساب («Couldn't play sticker sound»)، بينما 0:26 خدام.
//   • المدة كتتاخد من بيانات الرسالة المقتبسة إلا توفرت، وإلا بفحص
//     ffprobe/ffmpeg لملف مؤقت كيتمسح مباشرة. ما تعرفاتش؟ كنكملو
//     بلا قصّ — البناء ما كيتبقاش معلّق على الفحص.
// ─────────────────────────────────────────────────────────────────────────────

import crypto from 'crypto'
import https from 'https'
import fs from 'fs'
import path from 'path'
import { spawn } from 'child_process'

process.env.TMPDIR = path.join(process.cwd(), 'tmp')

const TMP_DIR = path.join(process.cwd(), 'tmp')
const MAX_SIZE = 25 * 1024 * 1024
const MAX_AUDIO_SECONDS = 30

// صورة سيلانا 512×512 (JPEG) مضمّنة — وجه الستيكر الافتراضي
const MASCOT_JPG_B64 = ''

let busy = false

function ensureTmp() {
    try { fs.mkdirSync(TMP_DIR, { recursive: true }) } catch {}
}

function sha256(buffer) { return crypto.createHash('sha256').update(buffer).digest() }

// ── بناء protobuf يدوي (نفس كود الأصل) ──────────────────────────────────────
function varint(n) {
    const o = []
    while (n > 127) {
        o.push((n % 128) | 128)
        n = Math.floor(n / 128)
    }
    o.push(n)
    return Buffer.from(o)
}

function ld(f, body) {
    return Buffer.concat([varint(f * 8 + 2), varint(body.length), body])
}

// ── ffmpeg عبر pipes (نفس كود الأصل) ────────────────────────────────────────
function runFFmpeg(args, input) {
    return new Promise((resolve, reject) => {
        const p = spawn('ffmpeg', args)
        const out = []
        let err = ''
        p.stdout.on('data', (d) => out.push(d))
        p.stderr.on('data', (d) => { err += d })
        p.on('error', reject)
        p.on('close', (code) => {
            if (code !== 0) return reject(new Error(err.slice(-400) || ('ffmpeg exit ' + code)))
            resolve(Buffer.concat(out))
        })
        p.stdin.on('error', () => {})
        p.stdin.end(input)
    })
}

async function toOpus(input) {
    const buf = await runFFmpeg([
        '-v', 'error', '-i', 'pipe:0', '-vn', '-map_metadata', '-1',
        '-c:a', 'libopus', '-b:a', '64k', '-ar', '48000', '-ac', '1',
        '-f', 'ogg', 'pipe:1',
    ], input)
    return { buf: buf, mimetype: 'audio/ogg; codecs=opus' }
}

function toWebp(input) {
    return runFFmpeg([
        '-v', 'error', '-i', 'pipe:0', '-frames:v', '1',
        '-vf', 'scale=512:512:force_original_aspect_ratio=decrease,pad=512:512:(ow-iw)/2:(oh-ih)/2',
        '-c:v', 'libwebp', '-f', 'webp', 'pipe:1',
    ], input)
}

function parseWebp(b) {
    if (b.length < 30 ||
        b.toString('ascii', 0, 4) !== 'RIFF' ||
        b.toString('ascii', 8, 12) !== 'WEBP') throw new Error('Invalid WebP')
    const c = b.toString('ascii', 12, 16)
    if (c === 'VP8 ') {
        return { width: b.readUInt16LE(26) & 0x3fff, height: b.readUInt16LE(28) & 0x3fff, isAnimated: false }
    }
    if (c === 'VP8L') {
        return {
            width: 1 + (b[21] | ((b[22] & 0x3f) << 8)),
            height: 1 + ((b[22] >> 6) | (b[23] << 2) | ((b[24] & 0x0f) << 10)),
            isAnimated: false,
        }
    }
    if (c === 'VP8X') {
        return {
            width: 1 + b.readUIntLE(24, 3),
            height: 1 + b.readUIntLE(27, 3),
            isAnimated: (b[20] & 2) !== 0,
        }
    }
    throw new Error('Unsupported WebP chunk')
}

// ── الرفع المشفّر لخوادم واتساب ─────────────────────────────────────────────
// kind: 'audio' | 'sticker' — نفس HKDF ديال الأصل
const HKDF_INFO = { audio: 'WhatsApp Audio Keys', sticker: 'WhatsApp Image Keys' }

async function uploadEncrypted(conn, plain, kind) {
    const mediaKey = crypto.randomBytes(32)
    const expanded = Buffer.from(crypto.hkdfSync('sha256', mediaKey, Buffer.alloc(32), Buffer.from(HKDF_INFO[kind]), 112))
    const iv = expanded.subarray(0, 16)
    const cipherKey = expanded.subarray(16, 48)
    const cipher = crypto.createCipheriv('aes-256-cbc', cipherKey, iv)
    const enc = Buffer.concat([cipher.update(plain), cipher.final()])
    const mac = crypto.createHmac('sha256', expanded.subarray(48, 80)).update(iv).update(enc).digest().subarray(0, 10)
    const file = Buffer.concat([enc, mac])
    const fileEncSha256 = sha256(file)
    const base = {
        mediaKey: mediaKey,
        fileEncSha256: fileEncSha256,
        fileSha256: sha256(plain),
        fileLength: plain.length,
        mediaKeyTimestamp: Math.floor(Date.now() / 1000),
    }

    // الطريق 1: waUploadToServer ديال Baileys (طريقة الأصل)
    if (typeof conn.waUploadToServer === 'function') {
        ensureTmp()
        const tmp = path.join(TMP_DIR, 'sa-' + kind + '-' + crypto.randomBytes(8).toString('hex') + '.enc')
        fs.writeFileSync(tmp, file)
        try {
            const res = await conn.waUploadToServer(tmp, {
                fileEncSha256B64: fileEncSha256.toString('base64'),
                mediaType: kind,
            })
            if (!res || !res.directPath) throw new Error(kind + ' upload returned no directPath')
            base.url = res.mediaUrl || ('https://mmg.whatsapp.net' + res.directPath)
            base.directPath = res.directPath
            return base
        } finally {
            try { fs.unlinkSync(tmp) } catch {}
        }
    }

    // الطريق 2: رفع يدوي عبر media_conn (طريقة sticker.js عندنا)
    if (typeof conn.query !== 'function') throw new Error('upload-unavailable: لا waUploadToServer لا query')
    const tag = conn.generateMessageTag ? conn.generateMessageTag() : String(Date.now())
    const iq = await conn.query({
        tag: 'iq',
        attrs: { id: tag, to: 's.whatsapp.net', type: 'set', xmlns: 'w:m' },
        content: [{ tag: 'media_conn', attrs: {} }],
    })
    const mediaConn = (iq.content || []).find((v) => v.tag === 'media_conn')
    if (!mediaConn) throw new Error('media_conn ما تلقاتش')
    const auth = mediaConn.attrs ? mediaConn.attrs.auth : null
    if (!auth) throw new Error('auth ديال media_conn ما تلقاتش')
    const hosts = (mediaConn.content || []).filter((v) => v.tag === 'host').map((v) => v.attrs ? v.attrs.hostname : null).filter(Boolean)
    if (!hosts.length) throw new Error('host ديال الرفع ما تلقاش')
    const token = encodeURIComponent(fileEncSha256.toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, ''))
    const mediaPath = '/mms/' + kind
    let lastError = null
    for (const host of hosts) {
        try {
            const json = await new Promise((resolve, reject) => {
                const url = new URL('https://' + host + mediaPath + '/' + token + '?auth=' + encodeURIComponent(auth) + '&token=' + token)
                const req = https.request({
                    hostname: url.hostname, port: 443, path: url.pathname + url.search, method: 'POST',
                    headers: { 'Origin': 'https://web.whatsapp.com', 'Referer': 'https://web.whatsapp.com/', 'Content-Type': 'application/octet-stream', 'Content-Length': file.length },
                }, (res) => {
                    let body = ''
                    res.on('data', (c) => { body += c })
                    res.on('end', () => {
                        if (res.statusCode < 200 || res.statusCode >= 300) return reject(new Error('Upload فشل ' + res.statusCode + ': ' + body))
                        try { resolve(JSON.parse(body)) } catch { reject(new Error('Response ماشي JSON: ' + body)) }
                    })
                })
                req.on('error', reject)
                req.write(file)
                req.end()
            })
            const directPath = json.direct_path || json.directPath || json.url || json.path
            if (!directPath) throw new Error('directPath ما تلقاش')
            base.url = 'https://mmg.whatsapp.net' + directPath
            base.directPath = directPath
            return base
        } catch (e) { lastError = e }
    }
    throw lastError || new Error('كل hosts ديال الرفع فشلو')
}

// ── تنزيل الصوت المقتبس (مع إعادة محاولة عبر updateMediaMessage) ────────────
async function downloadAudio(conn, m, q) {
    try {
        const buf = await q.download()
        if (buf && buf.length) return Buffer.from(buf)
    } catch {}
    if (typeof conn.updateMediaMessage === 'function' && q.key && q.message) {
        try {
            const refreshed = await conn.updateMediaMessage({ key: q.key, message: q.message })
            const rmsg = refreshed && refreshed.message ? refreshed.message : null
            if (rmsg && rmsg.audioMessage) {
                const baileys = await import('baileys')
                const stream = await baileys.downloadContentFromMessage(rmsg.audioMessage, 'audio')
                const chunks = []
                for await (const chunk of stream) chunks.push(chunk)
                const buf = Buffer.concat(chunks)
                if (buf.length) return buf
            }
        } catch {}
    }
    return null
}

// ── مدة الصوت + القصّ (v3) ────────────────────────────────────────────────
// تشغيل أداة خارجية والتقاط stdout/stderr بلا ما نرميو على exit code
function spawnCapture(cmd, args, input) {
    return new Promise((resolve) => {
        let p = null
        try { p = spawn(cmd, args) } catch { return resolve(null) }
        const out = []
        const err = []
        p.stdout.on('data', (d) => out.push(d))
        p.stderr.on('data', (d) => err.push(d))
        p.on('error', () => resolve(null))
        p.on('close', () => resolve({
            stdout: Buffer.concat(out).toString('utf8'),
            stderr: Buffer.concat(err).toString('utf8'),
        }))
        p.stdin.on('error', () => {})
        try {
            if (input) p.stdin.end(input)
            else p.stdin.end()
        } catch {}
    })
}

function fmtDur(totalSeconds) {
    const s = Math.max(0, Math.round(totalSeconds))
    const m = Math.floor(s / 60)
    const r = s % 60
    return m + ':' + (r < 10 ? '0' : '') + r
}

// المدة من بيانات الرسالة المقتبسة إلا كانت متوفرة (seconds ديال Baileys)
function quotedSeconds(q) {
    if (!q) return null
    const cands = [q.seconds]
    if (q.msg) cands.push(q.msg.seconds)
    if (q.message) {
        if (q.message.audioMessage) cands.push(q.message.audioMessage.seconds)
        cands.push(q.message.seconds)
    }
    for (const v of cands) {
        const n = Number(v)
        if (isFinite(n) && n > 0) return n
    }
    return null
}

// فحص المدة بـ ffprobe/ffmpeg عبر ملف مؤقت (نفس نمط الرفع) كيتمسح مباشرة.
// كنرجعو null إلا فشل كلشي — المستدعي كيكمل بلا قصّ.
async function probeSeconds(buf) {
    ensureTmp()
    const tmp = path.join(TMP_DIR, 'sa-probe-' + crypto.randomBytes(8).toString('hex') + '.bin')
    try {
        fs.writeFileSync(tmp, buf)
        const fp = await spawnCapture('ffprobe', [
            '-v', 'error', '-show_entries', 'format=duration',
            '-of', 'default=noprint_wrappers=1:nokey=1', tmp,
        ], null)
        if (fp) {
            const n = parseFloat(String(fp.stdout).trim())
            if (isFinite(n) && n > 0) return n
        }
        const ff = await spawnCapture('ffmpeg', ['-v', 'info', '-i', tmp], null)
        if (ff) {
            const match = /Duration: (\d+):(\d+):(\d+(?:\.\d+)?)/.exec(ff.stderr || '')
            if (match) {
                const n = (Number(match[1]) * 3600) + (Number(match[2]) * 60) + Number(match[3])
                if (isFinite(n) && n > 0) return n
            }
        }
        return null
    } catch {
        return null
    } finally {
        try { fs.unlinkSync(tmp) } catch {}
    }
}

async function audioSeconds(q, buf) {
    const meta = quotedSeconds(q)
    if (meta !== null) return meta
    try { return await probeSeconds(buf) } catch { return null }
}

// قصّ الصوت (بصيغة opus/ogg بحال toOpus) لأول MAX_AUDIO_SECONDS ثانية
function trimAudioBuf(buf) {
    return runFFmpeg([
        '-v', 'error', '-i', 'pipe:0', '-vn', '-map_metadata', '-1',
        '-c:a', 'libopus', '-b:a', '64k', '-ar', '48000', '-ac', '1',
        '-t', String(MAX_AUDIO_SECONDS),
        '-f', 'ogg', 'pipe:1',
    ], buf)
}

const USAGE = (p) => '🎙️ *ستيكر صوتي* — ' + p + 'stickeraudio\n\n' +
    'رد على فويس ولا أوديو واكتب:\n' +
    '• ' + p + 'stickeraudio\n\n' +
    'غادي يتصايب ستيكر بصورة سيلانا والصوت ديالك مخبّي فيه — كيتسمع من الستيكر نفسه.\n' +
    '⚠️ ميزة تجريبية: ظهور الصوت كيبقى على حساب نسخة واتساب ديال اللي كيستقبل.'


// ── اختيار الستيكر المعلّق (v2.1) ──────────────────────────────────────────
// فالذاكرة فقط: المفتاح = الشات + المرسل، القيمة = بايتات الوسائط + الوقت.
// ما كيتكتب حتى شي حاجة فالديسك، وكيتمسح ملي كيستعمل ولا كتسالي مدتو.
const PICK_TTL = 90 * 1000
const pendingPicks = new Map()

function pickKeyOf(m) {
    const sender = m.sender || m.participant || ''
    return String(m.chat || '') + '|' + String(sender)
}

// تجهيز الصورة المختارة لصيغة الستيكر:
//  • WebP جاهز (ستيكر واتساب) → كيستعمل كما هو بعد التحقق من البنية
//  • صورة عادية → تحويل بـ ffmpeg (نفس toWebp ديال v1)، وإلا sharp إلا كان
//  • فشل الكل → كيرمي خطأ، والمستدعي كيرجع لصورة سيلانا بلا ما يطيح
async function prepareVisual(buf) {
    if (buf.length > 12 &&
        buf.toString('ascii', 0, 4) === 'RIFF' &&
        buf.toString('ascii', 8, 12) === 'WEBP') {
        return { buf: buf, webp: parseWebp(buf) }
    }
    try {
        const out = await toWebp(buf)
        return { buf: out, webp: parseWebp(out) }
    } catch {}
    try {
        const sharpMod = await import('sharp')
        const sharpFn = sharpMod.default || sharpMod
        const out = await sharpFn(buf)
            .resize(512, 512, { fit: 'contain', background: { r: 0, g: 0, b: 0, alpha: 0 } })
            .webp()
            .toBuffer()
        return { buf: out, webp: parseWebp(out) }
    } catch {}
    throw new Error('convert-failed: ما قدرتش نحوّل الصورة المختارة لصيغة ستيكر')
}

const USAGE2 = (p) => USAGE(p) + '\n\n🖼️ *بغيتي ستيكر من اختيارك؟*\n' +
    '1) رد على أي ستيكر ولا صورة واكتب ' + p + 'stickeraudio\n' +
    '2) في ظرف 90 ثانية، رد على الأوديو ولا الفويس بنفس الأمر — غادي يتصايب بالستيكر اللي اخترتي.'

let handler = async (m, { conn, usedPrefix }) => {
    const p = usedPrefix || '.'
    const q = m.quoted ? m.quoted : null
    const pickKey = pickKeyOf(m)

    // ── خطوة 1: الرد على ستيكر/صورة = اختيار معلّق (كيبدّل أي اختيار سابق) ──
    if (q && (q.mtype === 'stickerMessage' || q.mtype === 'imageMessage')) {
        let pickedBuf = null
        try {
            const d = await q.download()
            if (d && d.length) pickedBuf = Buffer.from(d)
        } catch {}
        if (!pickedBuf) return m.reply('❌ ما قدرتش نحمل الستيكر/الصورة — عاود صيفطها وجرب مرة أخرى.')
        pendingPicks.set(pickKey, { buf: pickedBuf, mtype: q.mtype, ts: Date.now() })
        try {
            if (q.key && typeof conn.sendMessage === 'function') {
                await conn.sendMessage(m.chat, { react: { text: '🎵', key: q.key } })
            } else if (typeof m.react === 'function') {
                await m.react('🎵')
            }
        } catch {}
        return m.reply('✅ اخترت هاد الستيكر! دابا ردّ على الأوديو ولا الفويس اللي بغيتي يركّب عليه بنفس الأمر ' + p + 'stickeraudio — عندك 90 ثانية ⏳')
    }

    if (!q || q.mtype !== 'audioMessage') return m.reply(USAGE2(p))

    // ── حالة الاختيار المعلّق ديال هاد المستخدم فهاد الشات ──
    let pickedEntry = null
    let pickExpired = false
    const existingPick = pendingPicks.get(pickKey)
    if (existingPick) {
        if (Date.now() - existingPick.ts <= PICK_TTL) pickedEntry = existingPick
        else { pickExpired = true; pendingPicks.delete(pickKey) }
    }

    if (busy) return m.reply('⏳ كاينة معالجة خدامة دابا، سنى شوية وعاود.')
    busy = true
    try {
        const baileys = await import('baileys')
        const proto = baileys.proto
        if (!proto || !proto.Message) throw new Error('proto ما متوفرش فهاد النسخة ديال Baileys')

        const audioInput = await downloadAudio(conn, m, q)
        if (!audioInput) return m.reply('❌ ما قدرتش نحمل الصوت — عاود صيفطو وجرب مرة أخرى.')
        if (audioInput.length > MAX_SIZE) return m.reply('❌ الصوت كبير بزاف (الحد 25MB).')

        const origSeconds = await audioSeconds(q, audioInput)

        let opus = audioInput.subarray(0, 4).toString('ascii') === 'OggS'
            ? { buf: audioInput, mimetype: 'audio/ogg; codecs=opus' }
            : await toOpus(audioInput)

        // حدّ المدة (v3): إلا طال الصوت على MAX_AUDIO_SECONDS كنقصّو لأول
        // MAX_AUDIO_SECONDS ثانية — الستيكر الصوتي بصوت طويل ما كيتلعبش.
        // فشل القصّ؟ كنكملو بالصوت كامل (بلا ما نبلوكيو البناء).
        let trimNote = null
        if (origSeconds !== null && origSeconds > MAX_AUDIO_SECONDS) {
            try {
                const trimmedBuf = await trimAudioBuf(opus.buf)
                if (trimmedBuf && trimmedBuf.length) {
                    opus = { buf: trimmedBuf, mimetype: opus.mimetype }
                    trimNote = '✂️ الأوديو كان طويل (' + fmtDur(origSeconds) + ')، خديت منو غير أول ' + MAX_AUDIO_SECONDS + ' ثانية باش يخدم صوت الستيكر'
                }
            } catch {}
        }

        // مصدر الصورة: الاختيار المعلّق إلا كان صالح وقابل للتحويل، وإلا الماسكوت
        let stickerBuf = null
        let webp = null
        let usedPick = false
        let convertFailed = false
        if (pickedEntry) {
            try {
                const prep = await prepareVisual(pickedEntry.buf)
                stickerBuf = prep.buf
                webp = prep.webp
                usedPick = true
            } catch { convertFailed = true }
        }
        if (!stickerBuf) {
            stickerBuf = await toWebp(Buffer.from(MASCOT_JPG_B64, 'base64'))
            webp = parseWebp(stickerBuf)
        }

        const both = await Promise.all([
            uploadEncrypted(conn, opus.buf, 'audio'),
            uploadEncrypted(conn, stickerBuf, 'sticker'),
        ])
        const a = both[0]
        const s = both[1]

        // ── تجميع الرسالة المستقبلية (نفس بنية الأصل byte-for-byte) ──
        const mediaDomainInfo = (key) => ld(74, Buffer.concat([
            Buffer.from([0x08, 0x01]),
            ld(2, key),
        ]))

        const audioBytes = Buffer.concat([
            Buffer.from(proto.Message.AudioMessage.encode(
                proto.Message.AudioMessage.create({
                    url: a.url,
                    mimetype: opus.mimetype,
                    fileSha256: a.fileSha256,
                    fileEncSha256: a.fileEncSha256,
                    fileLength: a.fileLength,
                    mediaKey: a.mediaKey,
                    directPath: a.directPath,
                    mediaKeyTimestamp: a.mediaKeyTimestamp,
                })
            ).finish()),
            ld(17, mediaDomainInfo(a.mediaKey)),
        ])

        const stickerBase = Buffer.concat([
            Buffer.from(proto.Message.StickerMessage.encode(
                proto.Message.StickerMessage.create({
                    url: s.url,
                    fileSha256: s.fileSha256,
                    fileEncSha256: s.fileEncSha256,
                    mediaKey: s.mediaKey,
                    mimetype: 'image/webp',
                    height: webp.height,
                    width: webp.width,
                    directPath: s.directPath,
                    fileLength: s.fileLength,
                    mediaKeyTimestamp: s.mediaKeyTimestamp,
                    isAnimated: webp.isAnimated,
                    stickerSentTs: Date.now(),
                })
            ).finish()),
            ld(17, Buffer.concat([
                mediaDomainInfo(s.mediaKey),
                ld(82, varint(13001)),
            ])),
        ])

        const futureProofBody = ld(
            1,
            ld(26, Buffer.concat([
                stickerBase,
                ld(26, audioBytes),
            ]))
        )

        const RAW = Symbol('rawFields')
        const payload = proto.Message.create({
            messageContextInfo: {
                messageSecret: crypto.randomBytes(32),
            },
        })
        payload[RAW] = [[134, futureProofBody]]

        const originalEncode = proto.Message.encode
        proto.Message.encode = function (msg, w) {
            const out = originalEncode.call(this, msg, w)
            if (msg && msg[RAW]) {
                for (const pair of msg[RAW]) {
                    out.uint32(pair[0] * 8 + 2).bytes(pair[1])
                }
            }
            return out
        }

        try {
            await conn.relayMessage(m.chat, payload, {})
        } finally {
            proto.Message.encode = originalEncode
        }

        // إشعارات ما بعد البناء (النجاح فقط — الأخطاء كتعالج فـ catch لتحت)
        const trimSuffix = trimNote ? '\n' + trimNote : ''
        if (usedPick) {
            pendingPicks.delete(pickKey)
            await m.reply('✅ تصايب الستيكر الصوتي بالستيكر اللي اخترتي! 🎵' + trimSuffix)
        } else if (convertFailed) {
            pendingPicks.delete(pickKey)
            await m.reply('⚠️ ما قدرتش نحوّل الستيكر اللي اخترتي لصيغة مناسبة، استعملت صورة سيلانا.' + trimSuffix)
        } else if (pickExpired) {
            await m.reply('⏰ سالات مدة الاختيار، استعملت صورة سيلانا — عاود اختار الستيكر إلا بغيتيه' + trimSuffix)
        } else if (trimNote) {
            await m.reply(trimNote)
        }
    } catch (e) {
        const msg = String(e.message || e)
        return m.reply('❌ وقع مشكل أثناء صناعة الستيكر الصوتي.' + ((m.isOwner || m.fromMe) ? '\n🔧 ' + msg.slice(0, 280) : ''))
    } finally {
        busy = false
    }
}

handler.help = ['stickeraudio']
handler.tags = ['tools']
handler.command = ['stickeraudio']
handler.limit = false

export default handler
